<?php
declare(strict_types=1);ob_start();require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/super_app_v700.php';$u=v700_require_user();$uid=(int)$u['id'];$type=(string)($_GET['type']??$_POST['type']??'education');$flash='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$name=trim((string)($_POST['name']??''));if($name==='')throw new RuntimeException('Provider/business name is required.');$phone=trim((string)($_POST['phone']??''));$area=trim((string)($_POST['area']??''));$address=trim((string)($_POST['address']??''));$subtype=strtolower(trim((string)($_POST['subtype']??'')));if($type==='education'){if(!in_array($subtype,['school','college','academy','university','training_center','madrasa','other'],true))$subtype='academy';db()->prepare("INSERT INTO edu_institutions_v700(tenant_id,city_id,owner_user_id,name,slug,institution_type,phone,email,address,area,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,'pending',NOW(),NOW())")->execute([v700_tid(),v700_city_id(),$uid,$name,v700_slug($name),$subtype,$phone?:null,trim((string)($_POST['email']??''))?:null,$address?:null,$area?:null]);}elseif($type==='transport'){if(!in_array($subtype,['bus','van','taxi','ride_hailing','delivery','mixed'],true))$subtype='mixed';db()->prepare("INSERT INTO transport_operators_v700(tenant_id,city_id,owner_user_id,name,operator_type,phone,email,address,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,'pending',NOW(),NOW())")->execute([v700_tid(),v700_city_id(),$uid,$name,$subtype,$phone?:null,trim((string)($_POST['email']??''))?:null,$address?:null]);}elseif($type==='hotel'){db()->prepare("INSERT INTO tourism_hotels_v700(tenant_id,city_id,owner_user_id,name,slug,phone,email,address,area,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'pending',NOW(),NOW())")->execute([v700_tid(),v700_city_id(),$uid,$name,v700_slug($name),$phone?:null,trim((string)($_POST['email']??''))?:null,$address?:null,$area?:null]);}elseif($type==='restaurant'){db()->prepare("INSERT INTO tourism_restaurants_v700(tenant_id,city_id,owner_user_id,name,slug,cuisine,phone,address,area,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'pending',NOW(),NOW())")->execute([v700_tid(),v700_city_id(),$uid,$name,v700_slug($name),trim((string)($_POST['subtype']??''))?:null,$phone?:null,$address?:null,$area?:null]);}else throw new RuntimeException('Unsupported provider type.');$flash='Registration submitted for tenant review.';}}catch(Throwable $e){$err=$e->getMessage();}v700_public_header('Join ShahkotPK Super App','Register an education, transport, hotel or restaurant provider.','app');?>
<main><section class="v700-account-hero"><div class="v700-shell"><span class="v700-kicker">PROVIDER ONBOARDING</span><h1>Join the city network</h1><p>Providers are tenant-scoped and may require approval before public listing.</p></div></section><section class="v700-section soft"><div class="v700-shell" style="max-width:820px"><?php if($flash):?><div class="v700-alert success"><?=e($flash)?></div><?php endif;?><?php if($err):?><div class="v700-alert error"><?=e($err)?></div><?php endif;?><form method="post" class="v700-panel v700-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Provider Type<select name="type"><option value="education" <?=$type==='education'?'selected':''?>>School / Academy / Education</option><option value="transport" <?=$type==='transport'?'selected':''?>>Transport Operator</option><option value="hotel" <?=$type==='hotel'?'selected':''?>>Hotel / Guest House</option><option value="restaurant" <?=$type==='restaurant'?'selected':''?>>Restaurant</option></select></label><label>Name<input name="name" required></label><label>Subtype / Cuisine / Institution Type<input name="subtype" placeholder="academy, school, bus, mixed, Pakistani cuisine..."></label><div class="two"><label>Phone<input name="phone"></label><label>Email<input type="email" name="email" value="<?=e($u['email']??'')?>"></label></div><label>Area<input name="area"></label><label>Address<textarea name="address"></textarea></label><button class="v700-btn primary">Submit Provider Registration</button></form></div></section></main><?php v700_public_footer(); ?>
